const PL = {
  TAG: 'Booking.Availability',
  AMBITION: 'Patients can book an appointment whenever the clinic is open for booking.',
  SCALE: 'Percentage of minutes between 06:00 and 22:00 in which the booking service answers a health check.',
  METER: 'External monitor probes the booking endpoint every minute; monthly report.',
  GOAL: '99.5%',
  STRETCH: '99.9%',
};

function soCua(s) {
  var m = String(s).match(/(\d+(?:\.\d+)?)\s*%/);
  return m ? parseFloat(m[1]) : NaN;
}

function meets(pl, measured) {
  var g = soCua(pl.GOAL), s = soCua(pl.STRETCH);
  if (!isNaN(s) && measured >= s) return 'stretch';
  if (!isNaN(g) && measured >= g) return 'goal';
  return 'fail';
}
